const HIGH = 30; // alert at or above this
const BACK = 28; // back to normal at or below this
const temperature = Number(msg.payload);
if (!Number.isFinite(temperature)) {
    return null;
}
const hot = flow.get('hot') === true;
if (temperature >= HIGH && !hot) {
    flow.set('hot', true);
    msg.payload = 'Temperature is ' + temperature + ' C, above the limit of ' + HIGH + ' C.';
    return msg;
}
if (temperature <= BACK && hot) {
    flow.set('hot', false);
    msg.payload = 'Temperature is back to normal: ' + temperature + ' C.';
    return msg;
}
return null;
